issues=[
 {'id':'ISS-01','priority':'P1','feature':'Resilience','title':'Android input ANR during checkout-to-leaderboard navigation','test':'PAY-06','fact':'An Android ANR dialog appeared, and ActivityManager recorded a 5,112 ms MotionEvent timeout. Repeated Wait did not provide lasting recovery. Video 06 shows the ANR dialog at 00:50.','hypothesis':'Main/UI thread scheduling or rendering pressure; recording codec and emulator CPU contention are confounders. No root cause proved.','fix':'Profile main-thread blocking and rendering during modal dismissal, wallet errors and destination changes. Keep navigation responsive and recover without requiring process restart.','verify':'Repeat the exact missing-wallet → rapid Connect → Back → Leaderboard sequence 20 times on physical Android and the emulator, both recorded and unrecorded. Capture main-thread traces; require no ANR and timely input response.','evidence':[shot('038-current'),shot('040-weekly-rules'),'videos/06-commerce-anr.mp4','logs/anr-commerce.txt']},
 {'id':'ISS-02','priority':'P2','feature':'Hideout','title':'Outfit cards leave an empty third column on the primary test size','test':'SHOP-02','fact':'Both grids display two narrow columns with a large empty right strip at 1080×2400/420 dpi. Small profile fits three columns.','hypothesis':'Width formula uses window width while the actual scroll content is narrower, possibly with fractional rounding.','fix':'Compute card width from measured container width and gaps so the intended column count fits. This reduces unnecessary scrolling and balances the shop.','verify':'At both tested densities and an intermediate width, show all columns without overflow, large unused strips or clipped fixed actions.','evidence':[shot('051-solana-scroll'),shot('060-outfit-scroll'),shot('094-small-hideout-scroll')]},
 {'id':'ISS-03','priority':'P2','feature':'Payments','title':'Pass and skin checkout hide the actionable missing-wallet reason','test':'PAY-04','fact':'No compatible wallet is installed. Pass/skin show a generic wallet request failure, while Add Credits names the missing-wallet condition.','hypothesis':'Different error presentation paths or retained wallet error state.','fix':'Use the specific missing-wallet message consistently and provide a clear install/open-wallet route plus Retry. The player should know what to do without sharing diagnostics.','verify':'On a clean device without wallet, open each purchase entry and confirm the same actionable message; install a test wallet and retry successfully.','evidence':[shot('002-pass-checkout'),shot('055-skin-checkout'),shot('036-pack-wallet-error')]},
 {'id':'ISS-04','priority':'P2','feature':'League','title':'History asks for wallet connection without a connect action','test':'LEAGUE-03','fact':'Disconnected History says “Connect your wallet to see your runs” but has no local Connect button.','hypothesis':'Empty state is informational text only.','fix':'Add Connect wallet in the empty state and return users to History after cancellation or connection.','verify':'From a disconnected launch, reach History and connect/cancel without leaving for the store; after connection fetch the actual account history.','evidence':[shot('047-history-empty'),'support/history.xml']},
 {'id':'ISS-05','priority':'P2','feature':'Collection','title':'First phone preview is blank before the model appears','test':'PHONE-03','fact':'Initial Frost capture after about two seconds shows an empty stage with rotation instructions. A later back view renders. Exact ready time is not known.','hypothesis':'Filament/model initialization is asynchronous without visible progress.','fix':'Show a loading state until the model is ready, then reveal rotation controls; provide retry/error feedback on failure.','verify':'Cold-open all phone previews on physical hardware and a throttled emulator; require immediate loading feedback and a visible model or actionable error.','evidence':[shot('064-phone-frost'),shot('065-frost-back'),'videos/07-hideout.webm']},
 {'id':'ISS-06','priority':'P2','feature':'Environment','title':'Software-renderer black-frame artifact','test':'RES-04','fact':'Tutorial produced a black lower frame with swiftshader_indirect; the later host-GPU run did not show it.','hypothesis':'Software-renderer compatibility or capture path rather than confirmed app-wide rendering defect.','fix':'Document the supported emulator graphics configuration and investigate only if it reproduces on supported physical GPUs.','verify':'Repeat tutorial on a physical Android device and host-GPU emulator with identical APK; inspect both display and recording.','evidence':[shot('013-guide-next'),'logs/swiftshader-filtered.txt']}
]
