css='''*{box-sizing:border-box}html{scroll-behavior:smooth}body{margin:0;background:#0c1118;color:#e7edf5;font:16px/1.6 system-ui,-apple-system,sans-serif}main{max-width:1240px;margin:auto;padding:40px 28px 80px}header{padding:26px 0 30px}.eyebrow{color:#86d7bd;font-size:12px;font-weight:800;letter-spacing:2px}h1{font-size:clamp(34px,5vw,65px);line-height:1.08;letter-spacing:-2px;max-width:940px;margin:20px 0}h2{font-size:29px;line-height:1.25;margin:0 0 22px}h3{font-size:20px;line-height:1.3;margin:12px 0}.lead{max-width:810px;color:#b2c3d4;font-size:19px}.verdict{margin:28px 0;padding:24px;border:1px solid #ef8767;background:#2c1d1d;border-radius:16px}.verdict b{color:#ffad91;letter-spacing:1px;font-size:13px}.verdict p{margin:10px 0 0}.counts{display:grid;grid-template-columns:repeat(4,1fr);gap:12px}.count{background:#141e29;border:1px solid #2d3c4e;border-radius:12px;padding:15px 20px;display:flex;align-items:center;gap:15px}.count strong{font-size:32px}.count span{font-size:13px}.muted{color:#98aec1}a{color:#a1ddf5;text-decoration:none}a:hover{text-decoration:underline}nav{display:flex;gap:7px;flex-wrap:wrap;padding:16px 0;border-top:1px solid #2b3b4a;border-bottom:1px solid #2b3b4a}nav a{background:#172430;border-radius:6px;padding:5px 10px;font-size:13px}section{padding-top:55px;scroll-margin-top:20px}.panel{background:#131e28;border:1px solid #293c4d;border-radius:14px;padding:24px;margin-bottom:18px}.split{display:grid;grid-template-columns:1fr 1fr;gap:20px}.findings li{margin:16px 0;padding-left:7px}.tag,.badge{display:inline-block;border-radius:6px;padding:4px 9px;font-size:12px;font-weight:800;background:#283b50}.P1,.failed{color:#ffb09e;background:#432721}.P2{color:#f3d490;background:#39311f}.passed{color:#a0e6c7}.blocked{color:#f3cf86}.not-tested{color:#a4b4c6}dt{color:#9bb2c5;font-size:12px;font-weight:700;text-transform:uppercase;margin-top:12px}dd{margin:3px 0 0;overflow-wrap:anywhere}.mono,code{font-family:ui-monospace,monospace;font-size:12px}.evidence{display:flex;gap:14px;flex-wrap:wrap;align-items:start;margin-top:15px}.evidence>a:not(.thumb){display:block;border:1px solid #385069;padding:7px 10px;border-radius:6px;font-size:12px}.thumb{display:block;width:130px;background:#0b131b;border:1px solid #31465c;border-radius:8px;overflow:hidden}.thumb img{width:100%;height:170px;object-fit:cover;object-position:top}.thumb span{display:block;padding:6px;line-height:1.25;font-size:10px;overflow-wrap:anywhere}.filters{display:flex;align-items:end;gap:12px;flex-wrap:wrap;margin-bottom:16px;background:#14212e;padding:16px;border-radius:10px}.filters label{font-size:12px;color:#a7bfd2;display:flex;flex-direction:column;gap:5px}select,input,button{font:inherit;background:#0e1720;color:#e4edf4;border:1px solid #3a5267;border-radius:6px;padding:8px}input{min-width:200px}button{cursor:pointer}.test{border:1px solid #293d4f;border-radius:9px;margin-bottom:8px;background:#111c26}.test summary{padding:14px;display:flex;align-items:center;gap:12px;cursor:pointer;flex-wrap:wrap}.test summary strong{flex:1;min-width:230px;font-size:14px}.test summary>.muted{font-size:11px}.test-body{padding:2px 22px 22px;border-top:1px solid #263848}.test-body p{margin:13px 0;font-size:14px}.journey{display:grid;grid-template-columns:140px 1fr;border-left:2px solid #4c9e89;margin-left:10px;padding:12px 22px;gap:20px}.journey time{color:#89d4bb;font-size:13px}.journey h3{margin-top:0}.table-wrap{overflow-x:auto}table{border-collapse:collapse;width:100%;font-size:13px;background:#131e28}th{text-align:left;color:#98c6c0;background:#192b35}th,td{padding:14px;vertical-align:top;border-bottom:1px solid #293e50}td:first-child{min-width:150px}.video-grid{display:grid;grid-template-columns:1fr 1fr;gap:18px}.video-grid video{display:block;width:100%;height:460px;background:#03070b;border-radius:8px}.timestamps{display:flex;gap:6px;flex-wrap:wrap}.timestamps button{font-size:12px}.gallery{display:grid;grid-template-columns:repeat(5,1fr);gap:14px}.gallery a{background:#14212b;border-radius:8px;overflow:hidden;border:1px solid #2d4254}.gallery img{display:block;width:100%;aspect-ratio:9/16;object-fit:cover;object-position:top}.gallery span{display:block;font-size:10px;line-height:1.4;padding:7px;overflow-wrap:anywhere}.downloads{display:flex;flex-wrap:wrap;gap:12px}.downloads a{padding:10px 14px;border:1px solid #345369;border-radius:8px}.lightbox{position:fixed;inset:0;background:#000e;z-index:100;display:none;align-items:center;justify-content:center;padding:28px}.lightbox.open{display:flex}.lightbox img{max-width:94vw;max-height:90vh;object-fit:contain}.lightbox button{position:absolute;top:15px;right:20px;font-size:20px}.hidden{display:none!important}@media(max-width:800px){main{padding:20px 15px}.split,.video-grid{grid-template-columns:1fr}.counts{grid-template-columns:1fr 1fr}.gallery{grid-template-columns:repeat(3,1fr)}.journey{grid-template-columns:1fr;gap:0}.video-grid video{height:410px}}'''
js='''const q=s=>document.querySelector(s);function filter(){let n=0;document.querySelectorAll('.test').forEach(el=>{const ok=(!q('#resultFilter').value||el.dataset.result===q('#resultFilter').value)&&(!q('#featureFilter').value||el.dataset.feature===q('#featureFilter').value)&&(!q('#severityFilter').value||el.dataset.severity===q('#severityFilter').value)&&el.textContent.toLowerCase().includes(q('#search').value.toLowerCase());el.classList.toggle('hidden',!ok);if(ok)n++});q('#shown').textContent=n+' test records shown';document.querySelectorAll('.issue').forEach(el=>el.classList.toggle('hidden',!!q('#severityFilter').value&&el.dataset.severity!==q('#severityFilter').value))}document.querySelectorAll('select,input').forEach(el=>el.addEventListener('input',filter));filter();document.querySelectorAll('[data-lightbox]').forEach(el=>el.addEventListener('click',e=>{e.preventDefault();q('#large').src=el.getAttribute('href');q('#lightbox').classList.add('open')}));function closeLight(){q('#lightbox').classList.remove('open')}q('#lightbox').addEventListener('click',closeLight);document.addEventListener('keydown',e=>{if(e.key==='Escape')closeLight()});document.querySelectorAll('[data-video]').forEach(el=>el.addEventListener('click',()=>{const v=document.getElementById(el.dataset.video);v.currentTime=Number(el.dataset.time);v.play()}));'''
(P/'index.html').write_text(f'<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Steal a Seeker · Android code 27 QA</title><style>{css}</style></head><body><main>{body}</main><div class="lightbox" id="lightbox" role="dialog" aria-label="Screenshot enlarged"><button aria-label="Close enlarged screenshot">×</button><img id="large" alt="Enlarged actual emulator screenshot"></div><script>{js}</script></body></html>')
